window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[164]={"id":"164","numero":164,"titre":"Exanthèmes fébriles de l'enfant","objectifs":[{"id":"164-1","rang":"A","rubrique":"Diagnostic positif","titre":"Exanthèmes fébriles de l’enfant : type d’éruption","contenu":"<p>Un <span class=\"kw-def\">exanthème</span> est un <span class=\"kw-clinique\">érythème d'apparition brutale et transitoire</span> lié à une vasodilatation et <span class=\"kw-clinique\">s'effaçant à la vitropression</span>. Intensité variable, diffus ou de topographie spécifique, isolé ou associé à une <span class=\"kw-clinique\">atteinte muqueuse (énanthème)</span>. Il peut être bénin ou potentiellement grave.</p>\n\n      <p><strong>Description sémiologique des trois types classiques</strong> (termes désuets selon le Collège, mais structurants pour l'orientation) :</p>\n      <table >\n        <thead><tr><th>Type</th><th>Morbilliforme</th><th>Roséoliforme (rubéoliforme)</th><th>Scarlatiniforme</th></tr></thead>\n        <tbody>\n          <tr><th>Sémiologie</th><td><span class=\"kw-clinique\">Maculo-papuleux</span></td><td><span class=\"kw-clinique\">Macules</span></td><td><span class=\"kw-clinique\">Plaques / nappes diffuses</span></td></tr>\n          <tr><th>Couleur</th><td><span class=\"kw-clinique\">Rouge</span></td><td><span class=\"kw-clinique\">Rosé, pâle</span></td><td><span class=\"kw-clinique\">Rouge vif ou plus sombre</span></td></tr>\n          <tr><th>Relief</th><td>Léger relief (papuleux)</td><td>Sans relief (ou minime)</td><td><span class=\"kw-clinique\">Granité</span> à la palpation</td></tr>\n          <tr><th>Intervalle de peau saine</th><td>Confluent en plaques avec <span class=\"kw-clinique\">intervalles de peau saine</span></td><td><span class=\"kw-clinique\">Intervalles de peau saine</span></td><td><span class=\"kw-alerte\">Pas d'intervalle de peau saine</span> (d'un seul tenant)</td></tr>\n        </tbody>\n      </table>\n\n      <p><strong><span class=\"kw-def\">Classification</span> actuelle (Collège)</strong> — un même agent <span class=\"kw-etio\">viral</span> peut donner des éruptions de divers types :</p>\n      <table >\n        <thead><tr><th>Exanthèmes érythémateux</th><th>Exanthèmes maculo-papuleux</th><th>Exanthèmes vésiculo-pustuleux</th></tr></thead>\n        <tbody>\n          <tr>\n            <td>\n              <span class=\"kw-etio\">Scarlatine</span><br>\n              <span class=\"kw-etio\">Syndromes toxiniques</span> strepto / staphylo<br>\n              <span class=\"kw-etio\">Maladie de Kawasaki</span><br>\n              <span class=\"kw-etio\">Toxidermie médicamenteuse</span>\n            </td>\n            <td>\n              <span class=\"kw-etio\">Rougeole</span> ; <span class=\"kw-etio\">rubéole</span><br>\n              <span class=\"kw-etio\">Exanthème subit</span> ; <span class=\"kw-etio\">mégalérythème épidémique</span><br>\n              <span class=\"kw-etio\">Entérovirus</span><br>\n              <span class=\"kw-etio\">Maladie de Kawasaki</span> ; <span class=\"kw-etio\">urticaire</span><br>\n              <span class=\"kw-etio\">Toxidermie médicamenteuse</span>\n            </td>\n            <td>\n              <span class=\"kw-etio\">Varicelle</span><br>\n              <span class=\"kw-etio\">HSV</span> ; <span class=\"kw-etio\">zona</span><br>\n              <span class=\"kw-etio\">Entérovirus</span> (coxsackie : syndrome pieds-mains-bouche)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège terminologique.</strong> Le Collège de pédiatrie considère <span class=\"kw-clinique\">les</span> termes « morbilliforme », « scarlatiniforme »… comme <span class=\"kw-alerte\">désuets</span> et à abandonner au profit de la <span class=\"kw-def\">classification</span> érythémateux / maculopapuleux / vésiculopustuleux.\n      </div>","frequence":0},{"id":"164-2","rang":"A","rubrique":"Identifier une urgence","titre":"Exanthèmes fébriles de l’enfant : évaluation de la gravité","contenu":"<p>Devant toute <span class=\"kw-clinique\">éruption</span> fébrile, <strong>rechercher avant tout une <span class=\"kw-alerte\">urgence</span> diagnostique et thérapeutique</strong>. Six tableaux à reconnaître immédiatement :</p>\n\n      <table >\n        <thead><tr><th>Signe d'alerte</th><th>Diagnostic à évoquer</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-alerte\">Purpura fébrile</span> + troubles hémodynamiques</td><td><span class=\"kw-etio\">Méningococcie</span> (<span class=\"kw-alerte\">purpura fulminans</span>)</td></tr>\n          <tr><td><span class=\"kw-alerte\">Érythème fébrile</span> + troubles hémodynamiques</td><td><span class=\"kw-etio\">Syndrome toxinique</span> → <span class=\"kw-etio\">Toxic Shock Syndrome (TSS)</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Fièvre &gt; 5 jours</span></td><td><span class=\"kw-etio\">Maladie de Kawasaki</span></td></tr>\n          <tr><td>Lésions érythémateuses circonscrites, <span class=\"kw-clinique\">infiltrées et douloureuses</span></td><td><span class=\"kw-etio\">Dermohypodermite bactérienne</span>, <span class=\"kw-clinique\">fasciite</span></td></tr>\n          <tr><td><span class=\"kw-alerte\">Ulcérations muqueuses</span> et/ou <span class=\"kw-alerte\">décollements épidermiques extensifs</span></td><td><span class=\"kw-etio\">Stevens-Johnson</span>, <span class=\"kw-etio\">syndrome de Lyell</span>, <span class=\"kw-etio\">épidermolyse staphylococcique (SSS)</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">AEG</span> + <span class=\"kw-clinique\">adénopathies</span> + atteinte multiviscérale + anomalies hématologiques (<span class=\"kw-bio\">hyperéosinophilie</span>, hyperlymphocytose) sur prise médicamenteuse prolongée</td><td><span class=\"kw-etio\">DRESS syndrome</span></td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        <strong>Toxic Shock Syndrome (TSS).</strong> <span class=\"kw-alerte\">Choc</span> toxinique par infection grave à <span class=\"kw-etio\">staphylocoque</span> ou <span class=\"kw-etio\">streptocoque</span> (portes d'entrée : cutanée, pharyngée, ostéoarticulaire, pleuropulmonaire). Diagnostic = syndrome toxinique (<span class=\"kw-clinique\">érythème fébrile</span> + troubles hémodynamiques) + <span class=\"kw-alerte\">atteinte d'au moins 3 organes</span> :\n        <ul>\n          <li><strong>Digestive :</strong> <span class=\"kw-clinique\">vomissements</span>, diarrhée</li>\n          <li><strong>Musculaire :</strong> myalgies, élévation des <span class=\"kw-bio\">CPK</span></li>\n          <li><strong>Neurologique :</strong> désorientation, troubles de conscience</li>\n          <li><strong>Muqueuse :</strong> énanthème pharyngé, conjonctival, vaginal</li>\n          <li><strong>Rénale :</strong> <span class=\"kw-bio\">insuffisance rénale</span>, <span class=\"kw-bio\">leucocyturie</span></li>\n          <li><strong>Hépatique :</strong> élévation <span class=\"kw-bio\">bilirubine</span> / transaminases</li>\n          <li><strong>Hématologique :</strong> <span class=\"kw-bio\">thrombopénie</span></li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-warn\">\n        <strong>Toujours repérer un <span class=\"kw-def\">terrain</span> spécifique.</strong> Cas index ou <span class=\"kw-def\">contact</span> <span class=\"kw-alerte\">immunodéprimé</span> ou <span class=\"kw-alerte\">nouveau-né</span> ; <span class=\"kw-alerte\">femme enceinte dans l'entourage</span> (rougeole, rubéole, mégalérythème épidémique, varicelle).\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 151 — <span class=\"kw-clinique\">Méningite</span> - méningoencéphalite · 215 — <span class=\"kw-clinique\">Purpura</span> · 115 — Toxidermies</em></p>","frequence":0},{"id":"164-3","rang":"A","rubrique":"Diagnostic positif","titre":"Exanthèmes fébriles de l’enfant : orientation diagnostique","contenu":"<p>Le diagnostic est <strong>avant tout clinique</strong>. La démarche : analyser <span class=\"kw-clinique\">les</span> lésions, écarter une <span class=\"kw-alerte\">urgence</span>, rechercher les antécédents (vaccinations, contages, médicaments), replacer l'<span class=\"kw-clinique\">éruption</span> dans son contexte évolutif.</p>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/164/algorithme-cat-eruption-febrile.png\" alt=\"Algorithme : conduite à tenir devant une éruption fébrile de l'enfant — d'abord identifier une urgence (méningococcie, Stevens-Johnson/Lyell/SSS, DRESS, Kawasaki, Toxic Shock Syndrome), puis poursuivre la démarche diagnostique selon les données cliniques (exanthèmes érythémateux/maculopapuleux/vésiculopustuleux, exanthèmes viraux, toxidermies, maladies systémiques).\" loading=\"lazy\">\n        <figcaption>Fig. 38.1 — Conduite à tenir devant une éruption fébrile de l'enfant : (1) identifier rapidement une urgence, puis (2) poursuivre la démarche diagnostique selon les données cliniques. Source : fiche source EDN item 164 / Collège de Pédiatrie.</figcaption>\n      </figure>\n\n      <p><strong>Orientation selon le contexte et <span class=\"kw-clinique\">les</span> signes associés</strong> :</p>\n      <table >\n        <thead><tr><th>Cause</th><th>Infectieuse</th><th>Médicamenteuse</th></tr></thead>\n        <tbody>\n          <tr><th>Contexte</th><td>Contage épidémique ; enfant → virus surtout</td><td>Introduction d'un <span class=\"kw-etio\">médicament 5-14 jours avant</span></td></tr>\n          <tr><th>Présentation</th><td><span class=\"kw-clinique\">Fièvre</span>, syndrome grippal ; <span class=\"kw-clinique\">énanthème</span> ; <span class=\"kw-clinique\">adénopathies</span></td><td><span class=\"kw-clinique\">Prurit</span> ; polymorphisme de l'<span class=\"kw-clinique\">éruption</span> ; <span class=\"kw-bio\">hyperéosinophilie</span></td></tr>\n        </tbody>\n      </table>\n\n      <p><strong>Orientation selon l'incubation</strong> (clé pour dater le contage) :</p>\n      <table >\n        <thead><tr><th>Infection</th><th>Germe</th><th>Incubation</th><th>Contagiosité</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Épidermolyse staphylococcique</span></td><td><span class=\"kw-etio\">S. aureus</span> (exfoliatines / <span class=\"kw-bio\">TSST1</span>)</td><td><span class=\"kw-chiffre\">48 h</span></td><td>—</td></tr>\n          <tr><td><span class=\"kw-etio\">Herpès</span> cutanéo-muqueux</td><td><span class=\"kw-etio\">HSV 1/2</span></td><td><span class=\"kw-chiffre\">2 à 7 j</span></td><td>Max. 1res heures de constitution des vésicules</td></tr>\n          <tr><td><span class=\"kw-etio\">Scarlatine</span></td><td><span class=\"kw-etio\">SGA</span> (toxine érythrogène)</td><td><span class=\"kw-chiffre\">3-5 j</span></td><td>Jusqu'à <span class=\"kw-chiffre\">48 h</span> après début ATB</td></tr>\n          <tr><td><span class=\"kw-etio\">Exanthème subit</span></td><td><span class=\"kw-etio\">HHV6/7</span></td><td><span class=\"kw-chiffre\">5-15 j</span></td><td>—</td></tr>\n          <tr><td><span class=\"kw-etio\">Rougeole</span></td><td><span class=\"kw-etio\">Morbillivirus</span></td><td><span class=\"kw-chiffre\">10-12 j</span></td><td><span class=\"kw-chiffre\">5 j avant → 5 j après</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Mégalérythème épidémique</span></td><td><span class=\"kw-etio\">Parvovirus B19</span></td><td><span class=\"kw-chiffre\">14 j</span></td><td>Phase pré-éruptive</td></tr>\n          <tr><td><span class=\"kw-etio\">Varicelle</span></td><td><span class=\"kw-etio\">VZV</span></td><td><span class=\"kw-chiffre\">14 j</span></td><td><span class=\"kw-chiffre\">1-2 j avant → croûtes (≥ J7)</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Rubéole</span></td><td><span class=\"kw-etio\">Togavirus</span> (rubivirus)</td><td><span class=\"kw-chiffre\">15-21 j</span></td><td><span class=\"kw-chiffre\">1 sem avant → 2 sem après</span></td></tr>\n          <tr><td><span class=\"kw-etio\">MNI</span></td><td><span class=\"kw-etio\">EBV</span></td><td><span class=\"kw-chiffre\">4 à 6 sem</span></td><td>Max. en aiguë, possible jusqu'à<span class=\"kw-chiffre\"> 6 mois</span></td></tr>\n        </tbody>\n      </table>\n\n      <p><strong>Examens complémentaires</strong> — l'indication est très limitée :</p>\n      <ul>\n        <li><strong>Enfant :</strong> <span class=\"kw-alerte\">aucun examen indispensable</span>, sauf suspicion de <span class=\"kw-etio\">scarlatine</span> (<span class=\"kw-bio\">TDR SGA / prélèvement de gorge</span>) ou de <span class=\"kw-etio\">Kawasaki</span> (<span class=\"kw-bio\">NFS</span>, <span class=\"kw-imagerie\">ETT</span>, <span class=\"kw-bio\">CRP/VS</span>, <span class=\"kw-bio\">BU</span>)</li>\n        <li><strong>Adulte (absence de cause évidente) :</strong> <span class=\"kw-bio\">NFS</span>, tests hépatiques, <span class=\"kw-bio\">sérologies</span> MNI, <span class=\"kw-bio\">TPHA/VDRL</span>, <span class=\"kw-bio\">VIH</span> (+ <span class=\"kw-bio\">PCR</span>)</li>\n        <li><strong>Femme enceinte :</strong> <span class=\"kw-bio\">sérologies</span> <span class=\"kw-bio\">toxoplasmose, rubéole, CMV, parvovirus B19, syphilis</span> selon statut de début de <span class=\"kw-ci\">grossesse</span></li>\n      </ul>\n\n      <div class=\"callout callout-danger\">\n        <strong>Distracteur d'annale.</strong> Devant un exanthème fébrile banal de l'enfant, <span class=\"kw-alerte\">il n'y a PAS d'indication à la CRP</span>. Ne pas la cocher en QCM.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 114 — Exanthème - erythrodermie</em></p>","frequence":0},{"id":"164-4","rang":"A","rubrique":"Etiologies","titre":"Maladies infectieuses éruptives : rougeole","contenu":"<p><strong>Agent :</strong> <span class=\"kw-etio\">morbillivirus</span> (paramyxovirus). Transmission <span class=\"kw-clinique\">aérienne directe</span>. Incubation <span class=\"kw-chiffre\">10-12 j</span>. <span class=\"kw-alerte\">Contagiosité très importante</span> de <span class=\"kw-chiffre\">5 j avant à 5 j après</span> l'<span class=\"kw-clinique\">éruption</span>. Nourrisson protégé jusqu'à <span class=\"kw-chiffre\">6 mois</span> par <span class=\"kw-clinique\">les</span> anticorps maternels ; immunité durable.</p>\n\n      <p><strong>Phase d'invasion (catarrhale, 2-4 j)</strong> :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Fièvre élevée</span></li>\n        <li><span class=\"kw-clinique\">Catarrhe oculo-respiratoire</span> : larmoiement, conjonctivite, rhinorrhée, <span class=\"kw-clinique\">toux</span></li>\n        <li><span class=\"kw-alerte\">Signe de Köplik</span> (pathognomonique, fin de période catarrhale) : <span class=\"kw-clinique\">taches punctiformes blanc-bleuté</span> sur muqueuse jugale <span class=\"kw-etio\">inflammatoire</span></li>\n      </ul>\n      <p><strong>Phase éruptive</strong> :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Exanthème maculopapuleux</span> non prurigineux, <span class=\"kw-clinique\">respectant des intervalles de peau saine</span></li>\n        <li>Début <span class=\"kw-clinique\">rétro-auriculaire</span> → extension <span class=\"kw-clinique\">descendante</span> en <span class=\"kw-chiffre\">24-48 h</span>, en <strong>une seule <span class=\"kw-clinique\">poussée</span></strong></li>\n        <li>Régression en <span class=\"kw-chiffre\">5-6 j</span> ; <span class=\"kw-clinique\">fièvre</span> décroissant à la généralisation ; persistance du catarrhe</li>\n      </ul>\n      <p><strong>Complications</strong> :</p>\n      <ul>\n        <li><strong>Infectieuses</strong> (réascension thermique) : bronchite, <span class=\"kw-alerte\">pneumopathie</span>, surinfection, OMA</li>\n        <li><strong>Neurologiques :</strong> <span class=\"kw-alerte\">encéphalite aiguë morbilleuse</span> post-éruptive (<span class=\"kw-chiffre\">1/1 000</span>) ; <span class=\"kw-alerte\">PESS de Van Bogaert</span> retardée <span class=\"kw-chiffre\">5-10 ans</span> (<span class=\"kw-chiffre\">1/100 000</span>)</li>\n      </ul>\n\n      <div class=\"callout callout-danger\">\n        <strong>Maladie à déclaration obl<span class=\"kw-chiffre\">iga</span>toire.</strong> Confirmation <span class=\"kw-ttt\">biologique</span> <span class=\"kw-alerte\">systématique</span> : <span class=\"kw-bio\">PCR</span> (salive, sang) ou, à défaut, <span class=\"kw-bio\">sérologie IgM</span>. PEC symptomatique (<span class=\"kw-ttt\">paracétamol</span> ; ATB <span class=\"kw-ttt\">amoxicilline-acide clavulanique</span> seulement si surinfection). <span class=\"kw-alerte\">Éviction de collectivité</span> jusqu'à <span class=\"kw-chiffre\">5 j</span> après le début de l'<span class=\"kw-clinique\">éruption</span>.\n      </div>\n      <div class=\"callout callout-warn\">\n        <strong><span class=\"kw-ttt\">Vaccination</span> ROR.</strong> <span class=\"kw-ttt\">Vaccin trivalent</span> : 1re dose à <span class=\"kw-chiffre\">12 mois</span>, 2e dose à <span class=\"kw-chiffre\">16-18 mois</span>. Couverture longtemps insuffisante en France (&lt;<span class=\"kw-chiffre\"> 90 %</span>) → épidémies récurrentes.\n      </div>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Pédiatrie.</em></p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 146 — <span class=\"kw-ttt\">Vaccination</span> · 27 — Prévention risques fœtaux</em></p>","frequence":0},{"id":"164-5","rang":"A","rubrique":"Etiologies","titre":"Maladies infectieuses éruptives : rubéole","contenu":"<p><strong>Agent :</strong> <span class=\"kw-etio\">rubivirus</span> (togavirus, virus à ARN). Transmission <span class=\"kw-clinique\">aérienne ou transplacentaire</span>. Incubation <span class=\"kw-chiffre\">15-21 j</span>. Contagiosité <span class=\"kw-chiffre\">1 sem avant → 2 sem après</span>. Maladie le plus souvent <span class=\"kw-clinique\">bénigne</span>, immunité durable.</p>\n\n      <p><strong>Phase d'invasion (≈ 1 sem)</strong> : <span class=\"kw-clinique\">fièvre modérée</span>, <span class=\"kw-clinique\">état général conservé</span>, <span class=\"kw-alerte\">absence de catarrhe</span> (notamment pas de <span class=\"kw-clinique\">toux</span>), ± <span class=\"kw-clinique\">céphalées</span> / courbatures / pharyngite.</p>\n      <p><strong>Phase éruptive</strong> :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Exanthème maculopapuleux</span> souvent <span class=\"kw-clinique\">plus pâle et plus petit</span> que la rougeole</li>\n        <li>Atteinte de la <span class=\"kw-clinique\">face</span> puis extension au thorax ; une seule <span class=\"kw-clinique\">poussée</span> sur <span class=\"kw-chiffre\">72 h</span> (caractère <span class=\"kw-clinique\">fugace</span>)</li>\n        <li>Signes associés : <span class=\"kw-clinique\">adénopathies occipitales</span>, <span class=\"kw-clinique\">splénomégalie</span></li>\n      </ul>\n      <p><strong>Complications</strong> : <span class=\"kw-bio\">purpura thrombopénique</span> post-éruptif (<span class=\"kw-chiffre\">1/3 000</span>), arthralgies/arthrites (surtout adulte), <span class=\"kw-alerte\">encéphalite</span> (rare).</p>\n\n      <div class=\"callout callout-danger\">\n        <strong>Risque <span class=\"kw-ci\">tératogène</span> majeur.</strong> Chez la femme enceinte <span class=\"kw-alerte\">non immunisée avant 18 SA</span> : <span class=\"kw-alerte\">rubéole congénitale</span> (mort fœtale, embryofœtopathie sévère). <span class=\"kw-def\">Contact</span> enfant contagieux ↔ femme enceinte séronégative <span class=\"kw-alerte\">formellement prohibé</span>. Vaccin vivant atténué <span class=\"kw-ci\">contre-indiqué pendant la grossesse</span> → <span class=\"kw-ttt\">vaccination</span> en post-partum.\n      </div>\n      <div class=\"callout callout-warn\">\n        <strong>À retenir.</strong> Diagnostic clinique <span class=\"kw-alerte\">difficile</span> → confirmation <span class=\"kw-bio\">IgM spécifiques</span> surtout en cas de <span class=\"kw-def\">contact</span> avec une femme enceinte. Maladie à <span class=\"kw-alerte\">déclaration obligatoire depuis 2018</span>. Pas d'éviction de collectivité obl<span class=\"kw-chiffre\">iga</span>toire.\n      </div>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Pédiatrie.</em></p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 27 — Prévention risques fœtaux · 146 — <span class=\"kw-ttt\">Vaccination</span></em></p>","frequence":0},{"id":"164-6","rang":"A","rubrique":"Etiologies","titre":"Maladies infectieuses éruptives : mégalérythème épidémique","contenu":"<p><strong>Agent :</strong> <span class=\"kw-etio\">parvovirus B19</span>. Survient par <span class=\"kw-clinique\">épidémies familiales ou scolaires</span>, âge <span class=\"kw-chiffre\">5-14 ans</span>. Transmission <span class=\"kw-clinique\">respiratoire</span>. Incubation <span class=\"kw-chiffre\">6-14 j</span>. Immunité durable.</p>\n\n      <p><strong>Phase d'invasion (2 j)</strong> : <span class=\"kw-clinique\">fièvre modérée</span>, <span class=\"kw-clinique\">état général conservé</span>, <span class=\"kw-clinique\">céphalées</span>, myalgies.</p>\n      <p><strong>Phase éruptive</strong> :</p>\n      <ul>\n        <li>Début aux <span class=\"kw-alerte\">joues rouges d'aspect souffleté</span> (s'atténuant en quelques jours)</li>\n        <li>Puis extension tronc/extrémités : <span class=\"kw-clinique\">aspect réticulé en « carte de géographie »</span>, en guirlande</li>\n        <li>Fluctuations sur <span class=\"kw-chiffre\">1-3 semaines</span> ; possible syndrome « gants et chaussettes »</li>\n        <li>Signes associés : arthralgies, arthrites (rares)</li>\n      </ul>\n\n      <div class=\"callout callout-danger\">\n        <strong>Complications selon le <span class=\"kw-def\">terrain</span>.</strong>\n        <ul>\n          <li><span class=\"kw-alerte\">Hémolyse chronique</span> (drépanocytose, sphérocytose, thalassémie) → <span class=\"kw-alerte\">anémie aiguë érythroblastopénique</span> (transfusion urgente si mal tolérée)</li>\n          <li><span class=\"kw-alerte\">Femme enceinte</span> → <span class=\"kw-alerte\">anasarque fœtoplacentaire</span>, avortement précoce</li>\n        </ul>\n      </div>\n      <div class=\"callout callout-warn\">\n        <strong>À retenir.</strong> Diagnostic <span class=\"kw-clinique\">clinique</span> ; confirmation (<span class=\"kw-bio\">PCR sanguine</span>, <span class=\"kw-bio\">IgM</span>) seulement si <span class=\"kw-def\">contact</span> femme enceinte ou enfant à hémolyse chronique. Pas de vaccin, pas d'éviction obl<span class=\"kw-chiffre\">iga</span>toire.\n      </div>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Pédiatrie.</em></p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 27 — Prévention risques fœtaux</em></p>","frequence":0},{"id":"164-7","rang":"A","rubrique":"Etiologies","titre":"Maladies infectieuses éruptives : exanthème subit","contenu":"<p>Aussi appelé <span class=\"kw-etio\">sixième maladie</span> ou <span class=\"kw-etio\">roséole infantile</span>. <strong>Agent :</strong> <span class=\"kw-etio\">HHV6</span> (plus rarement HHV7). Âge moyen <span class=\"kw-chiffre\">6-24 mois</span>. Transmission <span class=\"kw-clinique\">salivaire/respiratoire</span>. Incubation <span class=\"kw-chiffre\">5-15 j</span>. Infection quasi ubiquitaire.</p>\n\n      <p><strong>Phase d'invasion</strong> : <span class=\"kw-alerte\">fièvre isolée d'apparition brutale</span> jusqu'à <span class=\"kw-chiffre\">39-40 °C</span>, <span class=\"kw-clinique\">bien tolérée</span>, puis <span class=\"kw-alerte\">chute brutale</span> de la <span class=\"kw-clinique\">fièvre</span> à la phase éruptive.</p>\n      <p><strong>Phase éruptive</strong> :</p>\n      <ul>\n        <li>Début <span class=\"kw-chiffre\">1 à 7 j</span> après la <span class=\"kw-clinique\">fièvre</span> (en moyenne <span class=\"kw-chiffre\">3 j</span>)</li>\n        <li><span class=\"kw-clinique\">Maculopapules pâles</span> (assez semblables à la rubéole) sur <span class=\"kw-clinique\">visage et tronc</span></li>\n        <li>Disparition en <span class=\"kw-chiffre\">12-24 h</span> (fugace)</li>\n        <li><span class=\"kw-alerte\">Apyrexie contemporaine de l'éruption</span> = signe très caractéristique</li>\n      </ul>\n      <p><strong>Complications</strong> : <span class=\"kw-alerte\">crises fébriles simples</span> ; <span class=\"kw-alerte\">méningite</span>/<span class=\"kw-clinique\">méningo-encéphalite</span> (rares).</p>\n\n      <div class=\"callout callout-danger\">\n        <strong>Discriminant clé EDN.</strong> L'<span class=\"kw-clinique\">éruption</span> survient <span class=\"kw-alerte\">au moment où la fièvre tombe</span> (« <span class=\"kw-clinique\">fièvre</span> nue » puis éruption à la défervescence). Ce décalage chronologique est la signature de la roséole en QCM.\n      </div>\n      <div class=\"callout callout-warn\">\n        <strong>À retenir.</strong> Diagnostic <span class=\"kw-clinique\">clinique</span> ; <span class=\"kw-bio\">PCR HHV6</span> seulement si forme atypique. PEC <span class=\"kw-clinique\">ambulatoire symptomatique</span> (<span class=\"kw-ttt\">paracétamol</span>).\n      </div>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Pédiatrie.</em></p>","frequence":3},{"id":"164-8","rang":"A","rubrique":"Etiologies","titre":"Maladies infectieuses éruptives : mononucléose infectieuse","contenu":"<p>La <span class=\"kw-etio\">MNI</span> est la <span class=\"kw-clinique\">primo-infection</span> symptomatique par l'<span class=\"kw-etio\">EBV</span> (virus d'Epstein-Barr). Transmission <span class=\"kw-clinique\">salivaire</span> (« maladie du baiser », jouets sucés). <span class=\"kw-clinique\">Incubation longue</span> <span class=\"kw-chiffre\">30-50 j</span>. Âge classique adolescent ; chez le <span class=\"kw-clinique\">nourrisson</span> = souvent <span class=\"kw-clinique\">fièvre prolongée parfois isolée</span>.</p>\n\n      <p><strong>Clinique (hors <span class=\"kw-clinique\">éruption</span>)</strong> :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Fièvre</span> + <span class=\"kw-clinique\">asthénie profonde</span></li>\n        <li><span class=\"kw-clinique\">Angine</span> érythémato-pultacée ou <span class=\"kw-clinique\">pseudo-membraneuse</span> avec <span class=\"kw-clinique\">respect de la luette</span> (± <span class=\"kw-clinique\">purpura</span> du voile, <span class=\"kw-clinique\">œdème</span> de luette)</li>\n        <li><span class=\"kw-clinique\">Voix nasonnée</span> ; <span class=\"kw-clinique\">adénopathies cervicales bilatérales volumineuses</span> ; <span class=\"kw-clinique\">œdème</span> des paupières</li>\n        <li><span class=\"kw-clinique\">Splénomégalie</span> (<span class=\"kw-chiffre\">50 %</span>)</li>\n      </ul>\n      <p><strong>Sémiologie dermatologique</strong> : <span class=\"kw-clinique\">exanthème polymorphe</span> maculopapuleux ou papulovésiculeux souvent discret, <span class=\"kw-alerte\">favorisé par la prise d'ampicilline / amoxicilline</span>.</p>\n      <p><strong>Autres atteintes</strong> : <span class=\"kw-bio\">hépatite cytolytique</span> (fréquente, souvent <span class=\"kw-ttt\">biologique</span>) ; anémie hémolytique / thrombopénie auto-immunes (rares) ; <span class=\"kw-alerte\">obstruction aiguë des VAS</span> (hypertrophie amygdalienne).</p>\n\n      <p><strong>Paraclinique</strong> :</p>\n      <table >\n        <thead><tr><th>Examen</th><th>Résultat</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">Sérologie EBV</span> (confirmation)</td><td><span class=\"kw-clinique\">Primo-infection</span> : <span class=\"kw-bio\">IgM anti-VCA (+)</span> et <span class=\"kw-bio\">IgG anti-EBNA (−)</span></td></tr>\n          <tr><td><span class=\"kw-bio\">NFS</span></td><td><span class=\"kw-bio\">Syndrome mononucléosique</span> (souvent pris en défaut chez le nourrisson)</td></tr>\n          <tr><td><span class=\"kw-bio\">Bilan hépatique</span></td><td>Élévation modérée des transaminases (quasi constante)</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        <strong>Pièges EDN.</strong> <span class=\"kw-clinique\">Éruption</span> déclenchée par la prise d'<span class=\"kw-alerte\">amoxicilline</span> pour une « angine » → évoquer une MNI. Devant angine + <span class=\"kw-clinique\">splénomégalie</span>, redouter aussi une <span class=\"kw-alerte\">leucémie</span>.\n      </div>\n      <div class=\"callout callout-warn\">\n        <strong>À retenir.</strong> PEC <span class=\"kw-clinique\">symptomatique</span> + repos ; prévenir du caractère <span class=\"kw-clinique\">durable de l'asthénie</span>. Cause à connaître de <span class=\"kw-clinique\">fièvre prolongée du nourrisson</span>.\n      </div>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Pédiatrie.</em></p>","frequence":0},{"id":"164-9","rang":"A","rubrique":"Etiologies","titre":"Maladies infectieuses éruptives : scarlatine","contenu":"<p><strong>Agent :</strong> <span class=\"kw-etio\">Streptococcus pyogenes</span> (<span class=\"kw-etio\">streptocoque</span> β-hémolytique du groupe A, <span class=\"kw-etio\">SGA</span>) sécrétant une <span class=\"kw-etio\">toxine érythrogène</span>. Forme <span class=\"kw-clinique\">bénigne du syndrome toxinique</span> (forme sévère = TSS). Transmission <span class=\"kw-clinique\">aérienne</span>. Incubation <span class=\"kw-chiffre\">3-5 j</span>. Contagiosité jusqu'à <span class=\"kw-chiffre\">48 h après le début de l'ATB</span>.</p>\n\n      <p><strong>Phase d'invasion (<span class=\"kw-chiffre\">24 h</span>)</strong> : <span class=\"kw-clinique\">fièvre 39-40 °C</span> avec <span class=\"kw-clinique\">frissons</span>, <span class=\"kw-clinique\">angine érythémateuse</span> (<span class=\"kw-clinique\">dysphagie</span>, <span class=\"kw-clinique\">tuméfaction</span> amygdalienne), <span class=\"kw-clinique\">douleurs abdominales</span> et <span class=\"kw-clinique\">vomissements</span>, <span class=\"kw-clinique\">adénopathies</span> sous-angulomaxillaires.</p>\n      <p><strong>Phase éruptive</strong> :</p>\n      <ul>\n        <li><strong>Énanthème :</strong> <span class=\"kw-clinique\">glossite</span> — langue d'abord <span class=\"kw-clinique\">saburrale</span> (enduit blanc) → dépapillation de la périphérie vers le centre (« V lingual ») → aspect <span class=\"kw-alerte\">framboisé à J6</span></li>\n        <li><strong>Exanthème :</strong> <span class=\"kw-alerte\">vastes nappes rouge vif sans intervalle de peau saine</span>, sensation de <span class=\"kw-clinique\">granité</span>, prédominance aux <span class=\"kw-clinique\">plis de flexion</span>, <span class=\"kw-clinique\">respect des paumes/plantes et de la région péribuccale</span></li>\n        <li>Régression dès J6 → <span class=\"kw-clinique\">desquamation « en doigt de gant »</span> des extrémités</li>\n      </ul>\n\n      <div class=\"callout callout-danger\">\n        <strong>Confirmation immédiate.</strong> Diagnostic clinique + <span class=\"kw-bio\">TDR du streptocoque A</span> réalisé <span class=\"kw-alerte\">systématiquement avant antibiothérapie</span>. Le dosage des <span class=\"kw-bio\">ASLO/ASD</span> est <span class=\"kw-alerte\">inutile en phase aiguë</span>.\n      </div>\n      <div class=\"callout callout-warn\">\n        <strong>Traitement.</strong> <span class=\"kw-ttt\">Amoxicilline 50 mg/kg/j</span> en 2 prises pendant <span class=\"kw-chiffre\">6 jours</span> PO (identique à l'angine <span class=\"kw-etio\">bactérienne</span>). PEC ambulatoire ; <span class=\"kw-alerte\">éviction de collectivité 48 h après le début de l'ATB</span>. Pas de recherche d'<span class=\"kw-bio\">hématurie</span>/<span class=\"kw-bio\">protéinurie</span> à distance.\n      </div>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Pédiatrie.</em></p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 149 — Angine - rhinopharyngite</em></p>","frequence":4},{"id":"164-10","rang":"A","rubrique":"Etiologies","titre":"Maladies infectieuses éruptives : maladie de Kawasaki","contenu":"<p><span class=\"kw-def\">Vascularite aiguë multisystémique</span> (syndrome adéno-cutanéo-muqueux fébrile). Touche surtout l'enfant <span class=\"kw-chiffre\">&lt; 5 ans</span>, pic vers <span class=\"kw-chiffre\">1 an</span>. Pas d'explication physiopathologique unique (<span class=\"kw-def\">terrain</span> <span class=\"kw-etio\">génétique</span> + déclencheur <span class=\"kw-etio\">infectieux</span> probable + activation immunitaire endothéliale).</p>\n\n      <p><strong>Diagnostic de forme typique</strong> = <span class=\"kw-alerte\">fièvre ≥ 5 jours</span> (critère constant indispensable, résistante aux antipyrétiques et antibiotiques) <strong>+ <span class=\"kw-chiffre\">≥ 4</span> des 5 <span class=\"kw-def\">critères majeurs</span></strong> :</p>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Critère majeur</span></th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Conjonctivite</span></td><td>Bilatérale, non exsudative, indolore</td></tr>\n          <tr><td><span class=\"kw-clinique\">Atteinte buccopharyngée</span></td><td>Chéilite, stomatite, pharyngite</td></tr>\n          <tr><td><span class=\"kw-clinique\">Éruption cutanée</span></td><td>Maculopapuleuse polymorphe (tronc, membres) ; desquamation du siège précoce dès J5</td></tr>\n          <tr><td><span class=\"kw-clinique\">Atteinte des extrémités</span></td><td><span class=\"kw-clinique\">Érythème</span> palmoplantaire, <span class=\"kw-clinique\">œdème</span> ferme et douloureux ; desquamation tardive péri-unguéale &gt; J10</td></tr>\n          <tr><td><span class=\"kw-clinique\">Adénopathie cervicale</span></td><td><span class=\"kw-clinique\">Diamètre</span> <span class=\"kw-chiffre\">≥ 1,5 cm</span></td></tr>\n        </tbody>\n      </table>\n      <p>Autres signes évocateurs : <span class=\"kw-clinique\">hyperirritabilité</span> (quasi constante), <span class=\"kw-clinique\">réactivation de la cicatrice de BCG</span>. Existence de <span class=\"kw-clinique\">formes incomplètes</span> (<span class=\"kw-clinique\">fièvre</span> isolée + peu de critères).</p>\n      <p><strong>Paraclinique</strong> : diagnostic clinique, <span class=\"kw-alerte\">pas de marqueur spécifique</span> ; <span class=\"kw-bio\">CRP/VS élevées</span> quasi constantes, hyperleucocytose, <span class=\"kw-bio\">hyperplaquettose tardive</span>, <span class=\"kw-bio\">leucocyturie amicrobienne</span> évocatrice.</p>\n\n      <div class=\"callout callout-danger\">\n        <strong>Gravité = atteinte coronarienne.</strong> Complications cardiovasculaires : initialement <span class=\"kw-alerte\">myocardite/péricardite</span>, puis <span class=\"kw-alerte\">dilatation voire anévrismes des coronaires</span>. <span class=\"kw-imagerie\">Échographie cardiaque transthoracique systématique</span> au diagnostic puis en <span class=\"kw-def\">suivi</span>.\n      </div>\n      <div class=\"callout callout-warn\">\n        <strong>Traitement (<span class=\"kw-alerte\">urgence</span>).</strong> <span class=\"kw-alerte\">Hospitalisation systématique</span> en phase aiguë. <span class=\"kw-ttt\">Immunoglobulines polyvalentes IV</span> (stoppent l'inflammation, préviennent l'atteinte cardiaque) + <span class=\"kw-ttt\">aspirine</span> (anti-<span class=\"kw-etio\">inflammatoire</span> en aigu puis <span class=\"kw-ttt\">antiagrégant</span>). Toujours évoquer Kawasaki devant une <span class=\"kw-alerte\">fièvre ≥ 5 jours</span>.\n      </div>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Pédiatrie.</em></p>","frequence":2},{"id":"164-11","rang":"A","rubrique":"Etiologies","titre":"Maladies infectieuses éruptives : varicelle","contenu":"<p><span class=\"kw-clinique\">Primo-infection</span> par le <span class=\"kw-etio\">VZV</span> (virus varicelle-<span class=\"kw-clinique\">zona</span>). Très fréquente (<span class=\"kw-chiffre\">600-700 000 cas/an</span> en France, <span class=\"kw-chiffre\">90 % avant 10 ans</span>, âge moyen <span class=\"kw-chiffre\">4 ans</span>). Transmission <span class=\"kw-clinique\">cutanéomuqueuse et respiratoire</span>. Incubation <span class=\"kw-chiffre\">14 j</span>. Contagiosité de <span class=\"kw-chiffre\">1-2 j avant les vésicules</span> jusqu'à la transformation <span class=\"kw-clinique\">croûteuse</span> de toutes <span class=\"kw-clinique\">les</span> lésions (≥ <span class=\"kw-chiffre\">J7</span>). Immunité durable ; le <span class=\"kw-etio\">zona</span> = réactivation.</p>\n\n      <p><strong>Phase éruptive</strong> (précédée d'un fébricule ± rash fugace) :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Lésion</span> élémentaire <span class=\"kw-clinique\">vésiculeuse</span> : « <span class=\"kw-clinique\">goutte de rosée sur peau saine</span> » → croûteuse et <span class=\"kw-clinique\">prurigineuse</span> de J4 à J10</li>\n        <li>Siège <span class=\"kw-clinique\">diffus, y compris cuir chevelu</span></li>\n        <li><span class=\"kw-alerte\">2-3 poussées successives</span> → coexistence d'<span class=\"kw-clinique\">éléments d'âges différents</span> (signe clé)</li>\n        <li>Signes associés : énanthème buccal érosif, micropolyadénopathies</li>\n      </ul>\n      <p><strong>Complications</strong> (<span class=\"kw-chiffre\">3-5 %</span>) :</p>\n      <ul>\n        <li><strong>Surinfections bactériennes</strong> (<span class=\"kw-etio\">S. aureus</span>, <span class=\"kw-etio\">SGA</span>) : <span class=\"kw-clinique\">impétigo</span>, <span class=\"kw-alerte\">dermohypodermite / fasciite nécrosante</span>, syndromes toxiniques</li>\n        <li><strong>Neurologiques :</strong> crises fébriles, <span class=\"kw-alerte\">cérébellite</span> (la plus fréquente), <span class=\"kw-alerte\">encéphalite</span></li>\n        <li><span class=\"kw-alerte\">Syndrome de Reye</span> (si prise d'<span class=\"kw-ttt\">aspirine</span>) ; pneumopathie varicelleuse ; <span class=\"kw-clinique\">purpura</span> thrombopénique</li>\n      </ul>\n\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-ci\">Contre-indication</span> formelle des <span class=\"kw-ttt\">AINS</span>.</strong> <span class=\"kw-ci\">Aspirine</span> et <span class=\"kw-ci\">ibuprofène</span> proscrits (risque de <span class=\"kw-alerte\">syndrome de Reye</span> et de <span class=\"kw-alerte\">fasciite nécrosante</span>). Antipyrétique = <span class=\"kw-ttt\">paracétamol</span> seul. <span class=\"kw-ttt\">Aciclovir IV</span> réservé aux immunodéprimés et formes graves/néonatales.\n      </div>\n      <div class=\"callout callout-warn\">\n        <strong>Terrains à risque de forme sévère.</strong> Immunodéprimés, adolescents &gt;<span class=\"kw-chiffre\"> 12 ans</span> / adultes, <span class=\"kw-alerte\">femmes enceintes</span>, nouveau-nés. PEC usuelle <span class=\"kw-clinique\">ambulatoire symptomatique</span> (ongles courts, antiseptique, antihistaminique si <span class=\"kw-clinique\">prurit</span>). Vaccin vivant atténué <span class=\"kw-ci\">CI grossesse / immunodéprimé</span>, hors <span class=\"kw-ttt\">calendrier vaccinal</span> systématique.\n      </div>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Pédiatrie.</em></p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 146 — <span class=\"kw-ttt\">Vaccination</span></em></p>","frequence":1}],"astuces":[{"type":"danger","titre":"Purpura fébrile = purpura fulminans jusqu'à preuve du contraire","contenu":"Toute fièvre + <strong>purpura</strong> (pétéchies/ecchymoses) chez un enfant = <strong>urgence absolue</strong>. Injection immédiate de <span class=\"kw-ttt\">ceftriaxone 50 mg/kg IV/IM</span> AVANT le transfert hospitalier. C'est l'un des rares gestes qu'on fait avant d'examiner."},{"type":"info","titre":"Roséole = fièvre 3-4 jours + éruption à la défervescence chez le nourrisson","contenu":"Nourrisson 6 mois – 2 ans, fièvre élevée isolée 3–4 jours, <strong>bon état général</strong>, puis <strong>éruption rose pâle du tronc à la chute thermique</strong>. Diagnostic rétrospectif. Première cause de convulsion fébrile à cet âge."},{"type":"warn","titre":"Kawasaki = J5 de fièvre, échographie cardiaque","contenu":"Fièvre ≥ <strong><span class=\"kw-chiffre\">5 jours</span></strong> résistante + <span class=\"kw-chiffre\">4/5</span> critères (conjonctivite, chéilite/langue framboisée, atteinte extrémités, éruption, ADP cervicale) → <strong>échographie cardiaque + <span class=\"kw-ttt\">IgIV <span class=\"kw-chiffre\">2 g/kg</span></span> AVANT <span class=\"kw-chiffre\">J10</span></strong> pour éviter les anévrysmes coronaires."},{"type":"warn","titre":"Varicelle : pas d'aspirine (Reye), pas d'AINS (fasciite)","contenu":"Ne <strong>jamais</strong> donner d'aspirine (syndrome de Reye) ni d'AINS (fasciite nécrosante à streptocoque A) dans la varicelle. Paracétamol uniquement."}],"strategie":{"urgence":"<p><strong>Méningococcie <span class=\"q\">— <span class=\"kw-alerte\">purpura fulminans</span></span></strong></p><p>prise en charge <span class=\"kw-alerte\">sans délai</span> (cf. item 215 — <span class=\"kw-clinique\">Purpura</span> · item 151 — <span class=\"kw-clinique\">Méningite</span>)</p><ul><li><span class=\"kw-alerte\">Purpura fébrile</span> + <span class=\"kw-alerte\">troubles hémodynamiques</span> → <span class=\"kw-alerte\">urgence</span> vitale absolue</li></ul><p><strong>Toxic Shock Syndrome <span class=\"q\">— <span class=\"kw-alerte\">choc</span> toxinique</span></strong></p><p>infection grave à <span class=\"kw-etio\">staphylocoque</span> ou <span class=\"kw-etio\">streptocoque</span> (portes d'entrée cutanée, pharyngée, ostéoarticulaire, pleuropulmonaire)</p><ul><li><span class=\"kw-alerte\">Érythème fébrile</span> + <span class=\"kw-alerte\">troubles hémodynamiques</span> + <span class=\"kw-alerte\">atteinte d'au moins 3 organes</span></li></ul><p><strong>Maladie de Kawasaki <span class=\"q\">— avant l'atteinte coronarienne</span></strong></p><p><span class=\"kw-alerte\">hospitalisation systématique</span> + <span class=\"kw-imagerie\">échographie cardiaque transthoracique</span> au diagnostic</p><ul><li><span class=\"kw-clinique\">Fièvre</span> <span class=\"kw-chiffre\">≥ 5 jours</span> résistante aux antipyrétiques et antibiotiques</li><li><span class=\"kw-ttt\">Immunoglobulines polyvalentes IV</span> + <span class=\"kw-ttt\">aspirine</span></li></ul>","hospit":"<p><strong>Ambulatoire :</strong> la majorité des exanthèmes viraux (<span class=\"kw-etio\">rougeole</span>, <span class=\"kw-etio\">rubéole</span>, <span class=\"kw-etio\">mégalérythème épidémique</span>, <span class=\"kw-etio\">exanthème subit</span>, <span class=\"kw-etio\">MNI</span>, <span class=\"kw-etio\">scarlatine</span>, <span class=\"kw-etio\">varicelle</span>) → <span class=\"kw-clinique\">PEC symptomatique</span>.<br><strong><span class=\"kw-alerte\">Hospitalisation</span> :</strong> <span class=\"kw-etio\">maladie de Kawasaki</span> (systématique en phase aiguë) · <span class=\"kw-etio\">varicelle</span> de l'<span class=\"kw-alerte\">immunodéprimé</span> / du <span class=\"kw-alerte\">nouveau-né</span> / forme grave (<span class=\"kw-ttt\">aciclovir IV</span>) · <span class=\"kw-alerte\">anémie aiguë érythroblastopénique</span> sur hémolyse chronique (parvovirus B19).<br><strong><span class=\"kw-alerte\">Urgence</span> vitale :</strong> <span class=\"kw-alerte\">purpura fulminans</span> · <span class=\"kw-def\">Toxic Shock Syndrome</span>.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Purpura fébrile</span> + troubles hémodynamiques → <span class=\"kw-etio\">méningococcie</span> (<span class=\"kw-alerte\">purpura fulminans</span>)</li><li><span class=\"kw-alerte\">Érythème fébrile</span> + troubles hémodynamiques → <span class=\"kw-etio\">syndrome toxinique</span> (<span class=\"kw-def\">Toxic Shock Syndrome</span>)</li><li><span class=\"kw-clinique\">Fièvre</span> <span class=\"kw-chiffre\">&gt; 5 jours</span> → <span class=\"kw-etio\">maladie de Kawasaki</span></li><li>Lésions érythémateuses circonscrites, <span class=\"kw-clinique\">infiltrées et douloureuses</span> → <span class=\"kw-etio\">dermohypodermite bactérienne</span>, <span class=\"kw-clinique\">fasciite</span></li><li><span class=\"kw-alerte\">Ulcérations muqueuses</span> et/ou <span class=\"kw-alerte\">décollements épidermiques extensifs</span> → <span class=\"kw-etio\">Stevens-Johnson</span>, <span class=\"kw-etio\">syndrome de Lyell</span>, <span class=\"kw-etio\">épidermolyse staphylococcique (SSS)</span></li><li><span class=\"kw-clinique\">AEG</span> + <span class=\"kw-clinique\">adénopathies</span> + atteinte multiviscérale + <span class=\"kw-bio\">hyperéosinophilie</span> sur prise médicamenteuse prolongée → <span class=\"kw-etio\">DRESS syndrome</span></li><li><span class=\"kw-def\">Terrain</span> à risque : <span class=\"kw-alerte\">immunodéprimé</span>, <span class=\"kw-alerte\">nouveau-né</span>, <span class=\"kw-alerte\">femme enceinte dans l'entourage</span></li></ul>","principes":"<p>La prise en charge est <span class=\"kw-clinique\">le plus souvent uniquement symptomatique</span> (<span class=\"kw-ttt\">paracétamol</span>) et <span class=\"kw-clinique\">les</span> examens complémentaires d'indication <span class=\"kw-alerte\">très limitée</span>. Seules quelques situations imposent un traitement spécifique.</p><p><strong>Scarlatine</strong></p><p>PEC ambulatoire</p><ul><li><span class=\"kw-bio\">TDR du streptocoque A</span> systématique avant <span class=\"kw-ttt\">antibiothérapie</span></li><li><span class=\"kw-ttt\">Amoxicilline 50 mg/kg/j</span> en 2 prises pendant <span class=\"kw-chiffre\">6 jours</span> PO</li></ul><p><strong>Maladie de Kawasaki</strong></p><p><span class=\"kw-imagerie\">échographie cardiaque transthoracique</span> systématique (atteinte coronarienne)</p><ul><li><span class=\"kw-alerte\">Hospitalisation systématique</span> en phase aiguë</li><li><span class=\"kw-ttt\">Immunoglobulines polyvalentes IV</span> + <span class=\"kw-ttt\">aspirine</span></li></ul><p><strong>Varicelle</strong></p><p>ambulatoire : ongles courts, antiseptique, <span class=\"kw-ttt\">antihistaminique</span> si <span class=\"kw-clinique\">prurit</span></p><ul><li>Antipyrétique = <span class=\"kw-ttt\">paracétamol</span> seul</li><li><span class=\"kw-ci\">Aspirine</span> et <span class=\"kw-ci\">ibuprofène</span> proscrits (<span class=\"kw-alerte\">syndrome de Reye</span>, <span class=\"kw-alerte\">fasciite nécrosante</span>)</li><li><span class=\"kw-ttt\">Aciclovir IV</span> réservé aux immunodéprimés et formes graves / néonatales</li></ul><p><strong>Rougeole</strong></p><p>maladie à <span class=\"kw-alerte\">déclaration obligatoire</span></p><ul><li><span class=\"kw-clinique\">Traitement symptomatique</span> (<span class=\"kw-ttt\">paracétamol</span>)</li><li><span class=\"kw-ttt\">Amoxicilline-acide clavulanique</span> seulement si surinfection</li></ul><p><strong>Autres viroses <span class=\"q\">— rubéole, mégalérythème, exanthème subit, MNI</span></strong></p><ul><li><span class=\"kw-clinique\">Traitement symptomatique</span> (<span class=\"kw-ttt\">paracétamol</span>, repos)</li><li>MNI : prévenir du caractère <span class=\"kw-clinique\">durable de l'asthénie</span></li></ul>","suivi":"<p><strong>Déclaration obl<span class=\"kw-chiffre\">iga</span>toire :</strong> <span class=\"kw-etio\">rougeole</span> · <span class=\"kw-etio\">rubéole</span> (depuis 2018).<br><strong>Éviction de collectivité :</strong> <span class=\"kw-etio\">rougeole</span> jusqu'à <span class=\"kw-chiffre\">5 j</span> après le début de l'<span class=\"kw-clinique\">éruption</span> ; <span class=\"kw-etio\">scarlatine</span> jusqu'à <span class=\"kw-chiffre\">48 h</span> après le début de l'ATB. Pas d'éviction obligatoire pour rubéole et mégalérythème.<br><strong>Confirmation <span class=\"kw-ttt\">biologique</span> :</strong> <span class=\"kw-bio\">PCR / IgM</span> systématique pour la rougeole ; réservée au <span class=\"kw-def\">contact</span> d'une <span class=\"kw-alerte\">femme enceinte</span> (ou enfant à <span class=\"kw-alerte\">hémolyse chronique</span> pour le parvovirus B19) pour <span class=\"kw-clinique\">les</span> autres viroses.<br><strong>Kawasaki :</strong> <span class=\"kw-imagerie\">échographie cardiaque</span> au diagnostic puis en <span class=\"kw-def\">suivi</span> (<span class=\"kw-def\">dépistage</span> des <span class=\"kw-alerte\">anévrismes coronaires</span>).</p>"},"liensGlobaux":[{"href":"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/infectiologie/eruptions-febriles","label":"Pédia-univ — référentiel éruptions fébriles"}],"cards":[{"i":"2819d2f158f6","n":164,"o":"164-1","u":"Diagnostic positif","t":"Exanthèmes fébriles de l’enfant : type d’éruption","q":"Comment classifie-t-on actuellement les exanthèmes en pédiatrie selon le Collège ?","a":"<p>La classification actuelle privilégie une description basée sur l'aspect morphologique des lésions, groupant les exanthèmes en :</p><ul><li><strong>Exanthèmes érythémateux</strong> (ex: scarlatine, syndromes toxiniques)</li><li><strong>Exanthèmes maculo-papuleux</strong> (ex: rougeole, rubéole, exanthème subit)</li><li><strong>Exanthèmes vésiculo-pustuleux</strong> (ex: varicelle, HSV, syndrome pieds-mains-bouche)</li></ul>"},{"i":"cdae276d93f9","n":164,"o":"164-1","u":"Diagnostic positif","t":"Exanthèmes fébriles de l’enfant : type d’éruption","q":"Comment distinguer sémiologiquement un exanthème morbilliforme d'un exanthème roséoliforme d'un exanthème scarlatiniforme, termes historiquement utilisés ?","a":"<ul><li><strong>Morbilliforme :</strong> Il est <strong>maculo-papuleux</strong>, de couleur rouge, avec un léger relief, confluent en plaques mais avec des <strong>intervalles de peau saine</strong>.</li><li><strong>Roséoliforme (rubéoliforme) :</strong> Il est constitué de <strong>macules</strong> de couleur rosé et pâle, sans ou avec un minime relief, et des intervalles de peau saine.</li><li><strong>Scarlatiniforme :</strong> Il se présente sous forme de <strong>plaques ou nappes diffuses</strong>, de couleur rouge vif ou sombre, avec un aspect <strong>granité à la palpation</strong>, et <strong>sans intervalle de peau saine</strong>.</li></ul>"},{"i":"f530e22b67b4","n":164,"o":"164-1","u":"Diagnostic positif","t":"Exanthèmes fébriles de l’enfant : type d’éruption","q":"Quelle est la définition d'un exanthème chez l'enfant ?","a":"<p>Un exanthème est un <strong>érythème</strong> d'apparition <strong>brutale et transitoire</strong>, lié à une vasodilatation et s'effaçant à la vitropression. Il peut être diffus ou localisé, et est parfois associé à une atteinte muqueuse appelée énanthème.</p>"},{"i":"4d3acf1a1c3e","n":164,"o":"164-10","u":"Etiologies","t":"Maladies infectieuses éruptives : maladie de Kawasaki","q":"Quels sont les critères diagnostiques d'une forme typique de la maladie de Kawasaki ?","a":"<p>Le diagnostic de forme typique de la maladie de Kawasaki repose sur :</p><ul><li>Une <strong>fièvre ≥ 5 jours</strong> (critère constant et indispensable, résistante aux antipyrétiques et antibiotiques).</li><li><strong>Au moins 4</strong> des 5 critères majeurs suivants :</li><ul><li><strong>Conjonctivite bilatérale</strong>, non exsudative, indolore.</li><li><strong>Atteinte buccopharyngée</strong> : chéilite, stomatite, pharyngite.</li><li><strong>Éruption cutanée</strong> : maculopapuleuse polymorphe (tronc, membres) ; desquamation du siège précoce dès J5.</li><li><strong>Atteinte des extrémités</strong> : érythème palmoplantaire, œdème ferme et douloureux ; desquamation tardive péri-unguéale &gt; J10.</li><li><strong>Adénopathie cervicale</strong> de diamètre ≥ 1,5 cm.</li></ul></ul>"},{"i":"bb463ed705f0","n":164,"o":"164-10","u":"Etiologies","t":"Maladies infectieuses éruptives : maladie de Kawasaki","q":"Quelle est la définition de la maladie de Kawasaki et les enfants principalement touchés ?","a":"<p>La maladie de Kawasaki est une <strong>vascularite aiguë multisystémique</strong>, également appelée syndrome adéno-cutanéo-muqueux fébrile. Elle touche principalement les enfants de <strong>moins de 5 ans</strong>, avec un pic vers <strong>1 an</strong>.</p>"},{"i":"e625846777b7","n":164,"o":"164-10","u":"Etiologies","t":"Maladies infectieuses éruptives : maladie de Kawasaki","q":"Quelles sont les principales complications cardiovasculaires et le traitement de la maladie de Kawasaki ?","a":"<p>Les principales complications cardiovasculaires de la maladie de Kawasaki sont :</p><ul><li>Initialement : <strong>myocardite</strong> ou <strong>péricardite</strong>.</li><li>Plus tardivement : <strong>dilatation voire anévrismes</strong> des coronaires.</li></ul><p>Le traitement est une urgence et inclut :</p><ul><li>Hospitalisation systématique en phase aiguë.</li><li><strong>Immunoglobulines polyvalentes IV</strong> (stoppent l'inflammation, préviennent l'atteinte cardiaque).</li><li><strong>Aspirine</strong> (anti-inflammatoire en aigu puis antiagrégant).</p>"},{"i":"3533c1dc6cd7","n":164,"o":"164-11","u":"Etiologies","t":"Maladies infectieuses éruptives : varicelle","q":"Quels sont les traitements médicamenteux contre-indiqués ou à privilégier en cas de varicelle, et quelles sont les indications d'aciclovir ?","a":"<p>En cas de varicelle :</p><ul><li>Les <strong>AINS</strong> sont <strong>formellement contre-indiqués</strong>.</li><li>L'<strong>aspirine</strong> et l'<strong>ibuprofène</strong> sont <strong>proscrits</strong> en raison du risque de syndrome de Reye et de fasciite nécrosante.</li><li>L'antipyrétique de choix est le <strong>paracétamol seul</strong>.</li><li>L'<strong>aciclovir IV</strong> est réservé aux <strong>sujets immunodéprimés</strong>, aux <strong>formes graves</strong> ou aux <strong>formes néonatales</strong>.</li></ul>"},{"i":"4b88a247fc17","n":164,"o":"164-11","u":"Etiologies","t":"Maladies infectieuses éruptives : varicelle","q":"Quelles sont les principales complications de la varicelle ?","a":"<p>Les complications de la varicelle surviennent dans <strong>3 à 5 % des cas</strong> et incluent :</p><ul><li>Des <strong>surinfections bactériennes</strong> (par <em>S. aureus</em> ou SGA) pouvant donner un <strong>impétigo</strong>, une <strong>dermohypodermite/fasciite nécrosante</strong>, ou des syndromes toxiniques.</li><li>Des complications <strong>neurologiques</strong> : <strong>crises fébriles</strong>, <strong>cérébellite</strong> (la plus fréquente), ou <strong>encéphalite</strong>.</li><li>Un <strong>syndrome de Reye</strong> (en cas de prise d'aspirine).</li><li>Une <strong>pneumopathie varicelleuse</strong>.</li><li>Un <strong>purpura thrombopénique</strong>.</li></ul>"},{"i":"58ffd6ec3d93","n":164,"o":"164-11","u":"Etiologies","t":"Maladies infectieuses éruptives : varicelle","q":"Décrivez les signes cliniques cutanés et associés de la varicelle.","a":"<p>La phase éruptive de la varicelle est caractérisée par :</p><ul><li>Une lésion élémentaire <strong>vésiculeuse</strong>, décrite comme une « <strong>goutte de rosée sur peau saine</strong> », qui évolue ensuite en lésion croûteuse et est très <strong>prurigineuse</strong>.</li><li>Un siège <strong>diffus</strong> des lésions, y compris le <strong>cuir chevelu</strong>.</li><li>La survenue de <strong>2 à 3 poussées successives</strong>, entraînant la <strong>coexistence d'éléments d'âges différents</strong> (c'est un signe clé).</li><li>Des signes associés tels qu'un <strong>énanthème buccal érosif</strong> et des <strong>micropolyadénopathies</strong>.</li></ul>"},{"i":"6b972e50acf3","n":164,"o":"164-11","u":"Etiologies","t":"Maladies infectieuses éruptives : varicelle","q":"Comment se transmet la varicelle et quelle est sa période de contagiosité ?","a":"<p>La varicelle se transmet par voies <strong>cutanéomuqueuse et respiratoire</strong>. La période de contagiosité s'étend de <strong>1 à 2 jours avant l'apparition des vésicules jusqu'à la transformation croûteuse de toutes les lésions</strong>, soit généralement jusqu'à <strong>J7</strong> de l'éruption.</p>"},{"i":"a29421d085d3","n":164,"o":"164-11","u":"Etiologies","t":"Maladies infectieuses éruptives : varicelle","q":"Quels sont les terrains à risque de développer une forme sévère de varicelle ?","a":"<p>Les terrains à risque de forme sévère de varicelle incluent :</p><ul><li>Les <strong>immunodéprimés</strong>.</li><li>Les <strong>adolescents de plus de 12 ans</strong> et les <strong>adultes</strong>.</li><li>Les <strong>femmes enceintes</strong>.</li><li>Les <strong>nouveau-nés</strong>.</li></ul>"},{"i":"c4ae3cbad272","n":164,"o":"164-11","u":"Etiologies","t":"Maladies infectieuses éruptives : varicelle","q":"Quelle est l'étiologie de la varicelle et ses principales caractéristiques épidémiologiques ?","a":"<p>La varicelle est due à une primo-infection par le <strong>VZV (virus varicelle-zona)</strong>. Elle est très fréquente, touchant <strong>90 % des enfants avant 10 ans</strong>, avec un âge moyen de <strong>4 ans</strong> en France.</p>"},{"i":"0e1638cbb8ad","n":164,"o":"164-2","u":"Identifier une urgence","t":"Exanthèmes fébriles de l’enfant : évaluation de la gravité","q":"Quels sont les critères diagnostiques d'un Syndrome d'hypersensibilité médicamenteuse (DRESS syndrome) chez l'enfant ?","a":"<p>Le DRESS syndrome doit être évoqué chez un enfant sous médication prolongée présentant :</p><ul><li>Une <strong>altération de l'état général (AEG)</strong></li><li>Des <strong>adénopathies</strong></li><li>Une <strong>atteinte multiviscérale</strong></li><li>Des <strong>anomalies hématologiques</strong> (hyperéosinophilie, hyperlymphocytose)</li></ul>"},{"i":"a0396b9563ab","n":164,"o":"164-2","u":"Identifier une urgence","t":"Exanthèmes fébriles de l’enfant : évaluation de la gravité","q":"Quels tableaux cliniques doivent faire évoquer un Syndrome de Stevens-Johnson, de Lyell ou un Syndrome d'épidermolyse staphylococcique chez l'enfant fébrile ?","a":"<p>Devant des <strong>ulcérations muqueuses</strong> et/ou des <strong>décollements épidermiques extensifs</strong> chez un enfant fébrile, il faut évoquer un <strong>Syndrome de Stevens-Johnson</strong>, un <strong>Syndrome de Lyell</strong> ou un <strong>Syndrome d'épidermolyse staphylococcique</strong> (SSS).</p>"},{"i":"adaec750d3b0","n":164,"o":"164-2","u":"Identifier une urgence","t":"Exanthèmes fébriles de l’enfant : évaluation de la gravité","q":"Quels diagnostics graves doit-on évoquer et reconnaître immédiatement en présence d'un purpura fébrile associé à des troubles hémodynamiques chez l'enfant ?","a":"<p>En présence d'un <strong>purpura fébrile</strong> accompagné de <strong>troubles hémodynamiques</strong>, il faut évoquer et reconnaître immédiatement une <strong>méningococcie</strong>, notamment un <strong>purpura fulminans</strong>.</p>"},{"i":"b13e949adff5","n":164,"o":"164-2","u":"Identifier une urgence","t":"Exanthèmes fébriles de l’enfant : évaluation de la gravité","q":"Quand faut-il suspecter un Syndrome de Kawasaki devant un exanthème fébrile chez l'enfant ?","a":"<p>Un Syndrome de Kawasaki doit être suspecté devant un exanthème fébrile en présence d'une <strong>fièvre persistant plus de 5 jours</strong>.</p>"},{"i":"b2c96de4c298","n":164,"o":"164-2","u":"Identifier une urgence","t":"Exanthèmes fébriles de l’enfant : évaluation de la gravité","q":"Quels sont les signes d'alerte suggérant une dermohypodermite bactérienne ou une fasciite chez l'enfant fébrile ?","a":"<p>Il faut suspecter une dermohypodermite bactérienne ou une fasciite devant des <strong>lésions érythémateuses circonscrites, infiltrées et douloureuses</strong> chez un enfant fébrile.</p>"},{"i":"d847e8922508","n":164,"o":"164-2","u":"Identifier une urgence","t":"Exanthèmes fébriles de l’enfant : évaluation de la gravité","q":"Quelle est la première étape devant un exanthème fébrile chez l'enfant ?","a":"<p>Devant toute éruption fébrile chez l'enfant, il faut avant tout rechercher une <strong>urgence diagnostique et thérapeutique</strong>.</p>"},{"i":"fbc4ad8ced69","n":164,"o":"164-2","u":"Identifier une urgence","t":"Exanthèmes fébriles de l’enfant : évaluation de la gravité","q":"Qu'est-ce que le Toxic Shock Syndrome (TSS) et quels sont ses principaux critères de diagnostic ?","a":"<p>Le Toxic Shock Syndrome (TSS) est un choc toxinique secondaire à une infection grave à <strong>staphylocoque</strong> ou <strong>streptocoque</strong>. Le diagnostic est posé en présence d'un <strong>syndrome toxinique</strong> (érythème fébrile + troubles hémodynamiques) associé à l'atteinte d'au moins <strong>3 organes</strong> parmi :</p><ul><li><strong>Digestive</strong> : vomissements, diarrhée</li><li><strong>Musculaire</strong> : myalgies, élévation des CPK</li><li><strong>Neurologique</strong> : désorientation, troubles de conscience</li><li><strong>Muqueuse</strong> : énanthème pharyngé, conjonctival, vaginal</li><li><strong>Rénale</strong> : insuffisance rénale, leucocyturie</li><li><strong>Hépatique</strong> : élévation bilirubine / transaminases</li><li><strong>Hématologique</strong> : thrombopénie</li></ul>"},{"i":"002df5eb8de3","n":164,"o":"164-3","u":"Diagnostic positif","t":"Exanthèmes fébriles de l’enfant : orientation diagnostique","q":"Quelle est l'approche diagnostique initiale face à un exanthème fébrile chez l'enfant ?","a":"<p>Face à un exanthème fébrile chez l'enfant, la démarche diagnostique est avant tout <strong>clinique</strong>. Elle doit d'abord <strong>écarter une urgence</strong>, puis analyser les lésions, rechercher des antécédents (vaccinations, contages, médicaments) et replacer l'éruption dans son contexte évolutif.</p>"},{"i":"776aa9fe1f13","n":164,"o":"164-3","u":"Diagnostic positif","t":"Exanthèmes fébriles de l’enfant : orientation diagnostique","q":"Dans quels cas spécifiques des examens complémentaires sont-ils indiqués face à un exanthème fébrile chez l'enfant, selon les recommandations pour l'EDN ?","a":"<p>L'indication des examens complémentaires est très limitée chez l'enfant. Ils sont justifiés uniquement en cas de :</p><ul><li>Suspicion de <strong>scarlatine</strong> (recherche de streptocoque A par <strong>TDR SGA</strong> ou <strong>prélèvement de gorge</strong>).</li><li>Suspicion de <strong>maladie de Kawasaki</strong> (avec <strong>NFS</strong>, <strong>ETT</strong>, <strong>CRP/VS</strong>, <strong>BU</strong>).</li></ul><p>En l'absence de ces suspicions, <strong>aucun examen n'est indispensable</strong> pour un exanthème fébrile banal. La <strong>CRP n'est pas indiquée</strong> devant un exanthème fébrile banal de l'enfant.</p>"},{"i":"8ad99cbc2603","n":164,"o":"164-3","u":"Diagnostic positif","t":"Exanthèmes fébriles de l’enfant : orientation diagnostique","q":"Quelles sont les valeurs d'incubation caractéristiques pour la rougeole, la varicelle et l'exanthème subit, pathologies fréquentes d'exanthème fébrile de l'enfant ?","a":"<ul><li><strong>Rougeole</strong> (Morbillivirus) : incubation de <strong>10 à 12 jours</strong>.</li><li><strong>Varicelle</strong> (VZV) : incubation de <strong>14 jours</strong>.</li><li><strong>Exanthème subit</strong> (HHV6/7) : incubation de <strong>5 à 15 jours</strong>.</li></ul>"},{"i":"9a4b8f1b9982","n":164,"o":"164-3","u":"Diagnostic positif","t":"Exanthèmes fébriles de l’enfant : orientation diagnostique","q":"Comment différencier une cause infectieuse d'une cause médicamenteuse d'exanthème fébrile chez l'enfant ?","a":"<p>L'orientation diagnostique se fait selon le contexte et les signes associés :</p><ul><li>Pour une cause <strong>infectieuse</strong> : il existe souvent un <strong>contage épidémique</strong>, l'enfant présente généralement une <strong>fièvre</strong>, un syndrôme grippal, un <strong>énanthème</strong> ou des <strong>adénopathies</strong>.</li><li>Pour une cause <strong>médicamenteuse</strong> : l'introduction d'un médicament dans les <strong>5 à 14 jours précédant</strong> est un indice. La présentation inclut souvent du <strong>prurit</strong>, un <strong>polymorphisme de l'éruption</strong> et une <strong>hyperéosinophilie</strong>.</li></ul>"},{"i":"1a0e1197fb4d","n":164,"o":"164-4","u":"Etiologies","t":"Maladies infectieuses éruptives : rougeole","q":"Quel est le schéma de vaccination recommandé pour la rougeole en France ?","a":"<p>Le schéma de vaccination pour la rougeole en France utilise le vaccin trivalent <strong>ROR</strong> (Rougeole-Oreillons-Rubéole) :</p><ul><li>La <strong>première dose</strong> est administrée à <strong>12 mois</strong>.</li><li>La <strong>deuxième dose</strong> est administrée entre <strong>16 et 18 mois</strong>.</li></ul>"},{"i":"2035c428d5c9","n":164,"o":"164-4","u":"Etiologies","t":"Maladies infectieuses éruptives : rougeole","q":"Comment le diagnostic de rougeole est-il confirmé et quelle est la prise en charge clinique ?","a":"<p>La rougeole est une maladie à <strong>déclaration obligatoire</strong>. Le diagnostic est confirmé systématiquement par <strong>PCR</strong> (sur salive ou sang) ou, à défaut, par <strong>sérologie IgM</strong>. La prise en charge est <strong>symptomatique</strong> (paracétamol). Les antibiotiques (ex: amoxicilline-acide clavulanique) ne sont indiqués qu'en cas de surinfection bactérienne. Il est recommandé une <strong>éviction de collectivité</strong> jusqu'à 5 jours après le début de l'éruption.</p>"},{"i":"a1da209afe8a","n":164,"o":"164-4","u":"Etiologies","t":"Maladies infectieuses éruptives : rougeole","q":"Quelles sont les principales complications infectieuses et neurologiques de la rougeole ?","a":"<p>Les principales complications de la rougeole incluent :</p><ul><li><strong>Infectieuses</strong> (souvent signalées par une réascension thermique) : bronchite, pneumopathie, surinfections bactériennes (ex : otite moyenne aiguë - OMA).</li><li><strong>Neurologiques</strong> : <ul><li><strong>Encéphalite aiguë morbilleuse</strong> post-éruptive (1/1 000 cas).</li><li><strong>Panencéphalite subaiguë sclérosante (PESS) de Van Bogaert</strong>, une complication tardive et très grave, survenant 5 à 10 ans après l'infection (1/100 000 cas).</li></ul></li></ul>"},{"i":"c75da1b44c36","n":164,"o":"164-4","u":"Etiologies","t":"Maladies infectieuses éruptives : rougeole","q":"Quels sont les signes cliniques de la phase d'invasion (catarrhale) de la rougeole ?","a":"<p>La phase d'invasion de la rougeole, d'une durée de 2 à 4 jours, se caractérise par :</p><ul><li>Une <strong>fièvre élevée</strong>.</li><li>Un <strong>catarrhe oculo-respiratoire</strong> (larmoiement, conjonctivite, rhinorrhée, toux).</li><li>Le <strong>signe de Köplik</strong>, pathognomonique, apparaissant en fin de période catarrhale : des taches punctiformes blanc-bleuté sur la muqueuse jugale inflammatoire.</li></ul>"},{"i":"d1111af43964","n":164,"o":"164-4","u":"Etiologies","t":"Maladies infectieuses éruptives : rougeole","q":"Décrivez les caractéristiques de l'exanthème maculopapuleux de la rougeole et son évolution.","a":"<p>L'exanthème de la rougeole est <strong>maculopapuleux</strong>, <strong>non prurigineux</strong>, et respecte des intervalles de peau saine. Il débute dans la région <strong>rétro-auriculaire</strong> et s'étend de manière descendante en 24 à 48 heures, en une seule poussée. La régression se fait en 5 à 6 jours, la fièvre décroît à la généralisation de l'éruption, mais le catarrhe peut persister.</p>"},{"i":"fcc66c99e606","n":164,"o":"164-4","u":"Etiologies","t":"Maladies infectieuses éruptives : rougeole","q":"Comment est transmis l'agent responsable de la rougeole et quelle est sa contagiosité ?","a":"<p>L'agent responsable de la rougeole est un <strong>morbillivirus</strong> (paramyxovirus) transmis par <strong>voie aérienne directe</strong>. La contagiosité est très importante, débutant <strong>5 jours avant</strong> et persistant jusqu'à <strong>5 jours après l'éruption</strong>.</p>"},{"i":"15f8132416be","n":164,"o":"164-5","u":"Etiologies","t":"Maladies infectieuses éruptives : rubéole","q":"Quelles sont les principales complications de la rubéole chez l'enfant et l'adulte, et quel est le risque majeur chez la femme enceinte non immunisée ?","a":"<p>Les complications de la rubéole incluent :</p><ul><li>Un <strong>purpura thrombopénique post-éruptif</strong> (1/3000).</li><li>Des <strong>arthralgies/arthrites</strong>, surtout chez l'adulte.</li><li>Une <strong>encéphalite</strong>, rare.</li></ul><p>Chez la femme enceinte non immunisée avant 18 SA, le risque est <strong>tératogène majeur</strong>, pouvant entraîner une <strong>rubéole congénitale</strong> avec mort fœtale ou embryofœtopathie sévère.</p>"},{"i":"6e3bc24a954f","n":164,"o":"164-5","u":"Etiologies","t":"Maladies infectieuses éruptives : rubéole","q":"Quel est l'agent étiologique de la rubéole et ses principales caractéristiques de transmission et d'incubation ?","a":"<p>La rubéole est causée par le <strong>rubivirus</strong>, un togavirus à ARN. Sa transmission est <strong>aérienne</strong> ou <strong>transplacentaire</strong>. La période d'incubation est de <strong>15 à 21 jours</strong>.</p>"},{"i":"748838e16268","n":164,"o":"164-5","u":"Etiologies","t":"Maladies infectieuses éruptives : rubéole","q":"Comment se manifeste la phase d'invasion de la rubéole ?","a":"<p>La phase d'invasion, d'environ une semaine, est caractérisée par :</p><ul><li>Une <strong>fièvre modérée</strong>.</li><li>Un <strong>état général conservé</strong>.</li><li>L'<strong>absence de catarrhe</strong> (notamment pas de toux).</li><li>Parfois des céphalées, courbatures ou une pharyngite.</li></ul>"},{"i":"e5597f0882f2","n":164,"o":"164-5","u":"Etiologies","t":"Maladies infectieuses éruptives : rubéole","q":"Quels sont les signes cliniques de la phase éruptive de la rubéole et les signes associés ?","a":"<p>La phase éruptive de la rubéole se caractérise par :</p><ul><li>Un <strong>exanthème maculopapuleux</strong>, souvent plus pâle et plus petit que celui de la rougeole.</li><li>L'éruption débute sur la <strong>face</strong> et s'étend au thorax.</li><li>Elle se présente en une <strong>seule poussée fugace</strong> sur 72 heures.</li></ul><p>Les signes associés sont des <strong>adénopathies occipitales</strong> et une <strong>splénomégalie</strong>.</p>"},{"i":"ee2164e9fda7","n":164,"o":"164-5","u":"Etiologies","t":"Maladies infectieuses éruptives : rubéole","q":"Comment est posé le diagnostic de rubéole, et quelles sont les implications en termes de santé publique ?","a":"<p>Le diagnostic de rubéole est souvent <strong>clinique</strong> mais peut être difficile. Il est confirmé par la recherche d'<strong>IgM spécifiques</strong>, particulièrement en cas de contact avec une femme enceinte. La rubéole est une <strong>maladie à déclaration obligatoire</strong> depuis 2018. Il n'y a pas d'éviction de collectivité obligatoire.</p>"},{"i":"2130da67329d","n":164,"o":"164-6","u":"Etiologies","t":"Maladies infectieuses éruptives : mégalérythème épidémique","q":"Quand faut-il confirmer le diagnostic de mégalérythème épidémique et quelle est la prise en charge générale ?","a":"<p>Le diagnostic de mégalérythème épidémique est le plus souvent <strong>clinique</strong>. La confirmation par <strong>PCR sanguine</strong> ou recherche d'<strong>IgM</strong> n'est justifiée qu'en cas de <strong>contact chez une femme enceinte</strong> ou un <strong>enfant atteint d'hémolyse chronique</strong>. Il n'existe <strong>pas de vaccin</strong> et <strong>pas d'éviction obligatoire</strong>.</p>"},{"i":"b67d2331abec","n":164,"o":"164-6","u":"Etiologies","t":"Maladies infectieuses éruptives : mégalérythème épidémique","q":"Décrivez les phases cliniques successives du mégalérythème épidémique, y compris les caractéristiques de l'éruption.","a":"<p>Le mégalérythème épidémique évolue en deux phases :</p><ul><li>Une <strong>phase d'invasion</strong> (environ 2 jours) avec fièvre modérée, état général conservé, céphalées et myalgies.</li><li>Une <strong>phase éruptive</strong> caractérisée par :<ul><li>Un début aux <strong>joues rouges d'aspect souffleté</strong>, s'atténuant en quelques jours.</li><li>Puis une extension au tronc et aux extrémités avec un aspect <strong>réticulé en « carte de géographie » ou en guirlande</strong>.</li><li>L'éruption peut fluctuer sur 1 à 3 semaines, et un syndrome « gants et chaussettes » est possible.</li></ul></li></ul><p>Des arthralgies et arthrites (rares) peuvent aussi être associées.</p>"},{"i":"bdccac3bad55","n":164,"o":"164-6","u":"Etiologies","t":"Maladies infectieuses éruptives : mégalérythème épidémique","q":"Quel virus est responsable du mégalérythème épidémique et quelles sont ses caractéristiques épidémiologiques ?","a":"<p>Le mégalérythème épidémique est causé par le <strong>parvovirus B19</strong>. Il survient par épidémies familiales ou scolaires, touche principalement les enfants de <strong>5 à 14 ans</strong> et se transmet par <strong>voie respiratoire</strong>. L'incubation est de 6 à 14 jours et confère une immunité durable.</p>"},{"i":"def844b2ed08","n":164,"o":"164-6","u":"Etiologies","t":"Maladies infectieuses éruptives : mégalérythème épidémique","q":"Quelles sont les complications spécifiques du mégalérythème épidémique en fonction du terrain, notamment vis-à-vis de l'hémolyse chronique et de la femme enceinte ?","a":"<ul><li>Chez les patients atteints d'<strong>hémolyse chronique</strong> (drépanocytose, sphérocytose, thalassémie), le parvovirus B19 peut entraîner une <strong>anémie aiguë érythroblastopénique</strong> nécessitant une transfusion urgente si mal tolérée.</li><li>Chez la <strong>femme enceinte</strong>, l'infection peut causer un risque d'<strong>anasarque fœtoplacentaire</strong> et d'avortement précoce.</li></ul>"},{"i":"039475cde0ac","n":164,"o":"164-7","u":"Etiologies","t":"Maladies infectieuses éruptives : exanthème subit","q":"Quelles sont les complications possibles de l'exanthème subit (roséole infantile) ?","a":"<p>Les complications de l'exanthème subit sont les <strong>crises fébriles simples</strong>. Plus rarement, une <strong>méningite</strong> ou une <strong>méningo-encéphalite</strong> peuvent survenir.</p>"},{"i":"84a1ed4416d8","n":164,"o":"164-7","u":"Etiologies","t":"Maladies infectieuses éruptives : exanthème subit","q":"Quelle est la définition de l'exanthème subit, également appelé roséole infantile ?","a":"<p>L'exanthème subit, ou roséole infantile (aussi connue sous le nom de sixième maladie), est une maladie infectieuse éruptive de l'enfant, principalement due à l'<strong>HHV6</strong> (plus rarement HHV7). Elle touche typiquement les enfants de <strong>6 à 24 mois</strong> et se caractérise par une fièvre élevée suivie d'une éruption cutanée maculo-papuleuse fugace.</p>"},{"i":"895cbfd759b6","n":164,"o":"164-7","u":"Etiologies","t":"Maladies infectieuses éruptives : exanthème subit","q":"Quelles sont les caractéristiques de la phase éruptive de l'exanthème subit (roséole infantile) ?","a":"<p>La phase éruptive de l'exanthème subit survient <strong>1 à 7 jours après l'apparition de la fièvre</strong> (en moyenne 3 jours). Elle se manifeste par des <strong>maculopapules pâles</strong> (assez semblables à la rubéole) qui débutent sur le <strong>visage et le tronc</strong>. L'éruption est fugace, disparaissant en <strong>12-24 heures</strong>.</p>"},{"i":"cc42bc6d33e3","n":164,"o":"164-7","u":"Etiologies","t":"Maladies infectieuses éruptives : exanthème subit","q":"Comment se manifeste la phase d'invasion de l'exanthème subit (roséole infantile) ?","a":"<p>La phase d'invasion de l'exanthème subit est caractérisée par une <strong>fièvre isolée</strong>, d'apparition brutale, atteignant <strong>39-40 °C</strong>. Cette fièvre est généralement <strong>bien tolérée</strong> et évolue pendant 1 à 7 jours (en moyenne 3 jours), avant de chuter brutalement au début de la phase éruptive.</p>"},{"i":"ce6ce2cbcd6e","n":164,"o":"164-7","u":"Etiologies","t":"Maladies infectieuses éruptives : exanthème subit","q":"Quel est le signe clinique discriminant clé de l'exanthème subit (roséole infantile) à retenir à l'EDN ?","a":"<p>Le signe clinique discriminant clé de l'exanthème subit est l'<strong>apyrexie contemporaine de l'éruption</strong>, c'est-à-dire que l'<strong>éruption survient au moment où la fièvre tombe</strong>. Ce décalage chronologique est la signature de la roséole (la « fièvre nue » puis l'éruption à la défervescence).</p>"},{"i":"6a9eec6312f6","n":164,"o":"164-8","u":"Etiologies","t":"Maladies infectieuses éruptives : mononucléose infectieuse","q":"Comment définir la mononucléose infectieuse (MNI) et quel est son agent étiologique ?","a":"<p>La mononucléose infectieuse est la <strong>primo-infection symptomatique</strong> causée par l'<strong>EBV</strong> (Virus d'Epstein-Barr).</p>"},{"i":"986f3ab4c4b6","n":164,"o":"164-8","u":"Etiologies","t":"Maladies infectieuses éruptives : mononucléose infectieuse","q":"Quels sont les résultats des examens paracliniques permettant de confirmer le diagnostic de mononucléose infectieuse ?","a":"<ul><li><strong>Sérologie EBV</strong> (pour une primo-infection) : <strong>IgM anti-VCA positifs</strong> et <strong>IgG anti-EBNA négatifs</strong>.</li><li><strong>Numération Formule Sanguine (NFS)</strong> : présence d'un <strong>syndrome mononucléosique</strong> (souvent absent chez le nourrisson).</li><li><strong>Bilan hépatique</strong> : élévation modérée des transaminases (quasi constante).</li></ul>"},{"i":"9f95e9b456e1","n":164,"o":"164-8","u":"Etiologies","t":"Maladies infectieuses éruptives : mononucléose infectieuse","q":"Quel est un piège classique à l'EDN concernant le diagnostic de mononucléose infectieuse ?","a":"<p>Devant une <strong>éruption cutanée déclenchée par la prise d'amoxicilline</strong> chez un patient présentant une « angine », il faut fortement évoquer une <strong>mononucléose infectieuse</strong>.</p>"},{"i":"c23ce0beeb6d","n":164,"o":"164-8","u":"Etiologies","t":"Maladies infectieuses éruptives : mononucléose infectieuse","q":"Quels sont les signes cliniques non éruptifs évocateurs d'une mononucléose infectieuse ?","a":"<ul><li><strong>Fièvre</strong> et <strong>asthénie profonde</strong></li><li><strong>Angine érythémato-pultacée</strong> ou <strong>pseudo-membraneuse</strong> avec <strong>respect de la luette</strong> (parfois purpura du voile, œdème de luette, voix nasonnée)</li><li><strong>Adénopathies cervicales bilatérales volumineuses</strong></li><li>Œdème des paupières</li><li><strong>Splénomégalie</strong> (présente dans 50% des cas)</li></ul>"},{"i":"da933f487efb","n":164,"o":"164-8","u":"Etiologies","t":"Maladies infectieuses éruptives : mononucléose infectieuse","q":"Comment se manifeste l'exanthème de la mononucléose infectieuse et dans quel contexte peut-il être majoré ?","a":"<p>L'exanthème de la mononucléose infectieuse est <strong>polymorphe</strong>, généralement <strong>maculopapuleux</strong> ou <strong>papulovésiculeux</strong> et souvent discret. Il est <strong>fréquemment majoré</strong> suite à la prise d'<strong>ampicilline</strong> ou d'<strong>amoxicilline</strong>.</p>"},{"i":"46ca420ef0f9","n":164,"o":"164-9","u":"Etiologies","t":"Maladies infectieuses éruptives : scarlatine","q":"Décrivez l'aspect de l'exanthème et de l'énanthème de la scarlatine.","a":"<p>L'exanthème de la scarlatine se manifeste par de <strong>vastes nappes rouge vif</strong>, sans intervalle de peau saine, donnant une sensation de granité. Il prédomine aux plis de flexion et <strong>respecte les paumes/plantes et la région péribuccale</strong>. L'énanthème, quant à lui, est une <strong>glossite</strong> : la langue est d'abord saburrale, puis dépapillée de la périphérie vers le centre (en « V lingual »), pour devenir <strong>framboisée</strong> vers J6.</p>"},{"i":"4a9a2ca35444","n":164,"o":"164-9","u":"Etiologies","t":"Maladies infectieuses éruptives : scarlatine","q":"Comment se présente la phase d'invasion de la scarlatine ?","a":"<p>La phase d'invasion de la scarlatine (environ 24 heures) est caractérisée par :</p><ul><li>Une <strong>fièvre élevée</strong> (39-40 °C) avec frissons.</li><li>Une <strong>angine érythémateuse</strong> (dysphagie, tuméfaction amygdalienne).</li><li>Des douleurs abdominales et vomissements.</li><li>Des adénopathies sous-angulomaxillaires.</li></ul>"},{"i":"b85c8755e0d5","n":164,"o":"164-9","u":"Etiologies","t":"Maladies infectieuses éruptives : scarlatine","q":"Quel est le diagnostic et le traitement de la scarlatine ?","a":"<p>Le diagnostic de la scarlatine est principalement <strong>clinique</strong>, confirmé par un <strong>TDR du streptocoque A</strong> effectué systématiquement avant toute antibiothérapie. Le traitement repose sur l'<strong>amoxicilline 50 mg/kg/j</strong> en 2 prises par voie orale pendant <strong>6 jours</strong>.</p>"},{"i":"f5611bb1497d","n":164,"o":"164-9","u":"Etiologies","t":"Maladies infectieuses éruptives : scarlatine","q":"Quel est l'agent étiologique de la scarlatine et quelle est sa particularité ?","a":"<p>La scarlatine est causée par <strong><em>Streptococcus pyogenes</em></strong>, un streptocoque β-hémolytique du groupe A (SGA), qui sécrète une <strong>toxine érythrogène</strong>.</p>"}]};